import Foundation

// Sample photos, made for the redesign. Base64 JPEG. Made up people, design only.
extension RdPhotos {
    static func b64A(_ k: String) -> String? {
        switch k {
        case "n1": return ""
        case "n2": return ""
        case "n3": return ""
        case "n4": return ""
        case "b1": return ""
        case "b2": return ""
        case "b3": return ""
        case "b4": return ""
        default: return nil
        }
    }
}
